"""
Page object class of the DICOM Export dialog in the Monaco application.
"""
from interops.libraries.monaco.interactions.objects import monaco_dicom_export_objects
import interops.libraries.monaco.interactions.dicom_export as dcm_export

class DICOMExport():
    def __init__(self) -> None:
      dcm_export.await_dicom_export_dialog()

    def select_modalities(self, modalities: list):
        """
        Select the modalities to export.

        Note: Currently only used for "Images", "Structure Set", "Total Plan", may expand to include more.

        :param: modalities (list), the list of modalities to be exported,
               including one or some of "Images", "Structure Set", "Total Plan".
        """
        if "Images" in modalities:
            dcm_export.toggle_images_in_modalities_tree()
        if "Structure set" in modalities:
            dcm_export.toggle_structure_set_in_modalities_tree()
        if "Total Plan" in modalities:
            dcm_export.toggle_total_plan_in_modalities_tree()

    def use_monaco_patient_name_and_id(self, useIt:bool):
        """
        If to use Monaco patient Name and ID.

        :param: useIt (bool), indicating if use it or allow overrides.
        """
        dcm_export.click_use_monaco_patient_button(useIt)

    def override_values(self, patID=None, patName=None, blockAperturesID=None, planID=None ):
        """"
        Override the patient ID, patient Name, block/apertures ID, plan ID.
        Use None if not to override.

        :params: patID, Patient ID, patName, Patient Name, blockAperturesID, block apertures ID,
                planID, Plan ID.
        """
        dcm_export.override_values(patID, patName, blockAperturesID, planID)

    def select_destinations(self, selection:list):
        """
        Select desstinations to export. Other destinations that are not in the list will be checked off.

        :param: selection (list), the selected destinations, for example, ["File", "DCMWin"]
        """
        dcm_export.toggle_checkboxes_from_manual_dicom_export_destination_tree(selection)

    def map_machine(self, mapping:dict, remap:bool):
        """
        Map machine process.

        :params: mapping (dict)  the specified mapping of machine name pairs, can be empty.
                 remap (bool) if need remap when already mapped
        """
        dcm_export.open_map_machine()
        dcm_export.map_machine(mapping, remap)
        dcm_export.click_map_machine_ok_button()


    def set_rtplan_options(self, cfs=None, includeSetupBeam=None):
        """
        Set RTPlan options.

        :params: cfs, if to use Composite Field Sequencing. None to skip from this setting. True, check on, False: check off.
                 includeSetupBeam, if to include setup beamsg. None to skip from this setting. True, check on, False: check off.
        """
        if cfs is not None:
            dcm_export.toggle_cfs_button(cfs)
        if includeSetupBeam:
            dcm_export.toggle_include_setup_beams_button(includeSetupBeam)

    def set_mosaiq_options(self, courseID=None, intent=None, doseRate=None, toleranceName=None):
        """
        Set Mosaiq opitons by given parameters. If any paramter is None, its setting will be skipped

        :params: courseID, Course ID,  intent, the plan intent, doseRate, dose rate
                 toleranceName, a tolerance option in the tolerance table
        """
        dcm_export.open_mosaiq_options()
        if courseID:
            dcm_export.set_course_id(courseID)
        if intent:
            dcm_export.set_plan_intent(intent)
        if doseRate:
            dcm_export.set_dose_rate(doseRate)
        if toleranceName:
            dcm_export.select_mosaiq_tolerance_table(toleranceName)
        dcm_export.affirm_mosaiq_options()

    def click_export(self)->bool:
        """
        Click the Export button. If there is a pop up, confirm it.
        
        :return: True: if succeeded, False if failed
        """
        result = dcm_export.click_export_button()
        dcm_export.acknowledge_question(True)
        return result


